-- DRAFT ONLY — DO NOT APPLY TO PRODUCTION.
-- Target: MR RAHAMAN Business Ecosystem Supabase project.
-- Purpose: one-time bootstrap of the canonical organization and verified founder owner.
-- This is a review artifact, NOT a numbered Supabase migration generated by the CLI.
-- Before converting to a migration: review schema drift, role matrix, ACLs, triggers,
-- run in an isolated Supabase test project, run advisors, then obtain explicit approval.

begin;

create or replace function private.bootstrap_primary_organization_v1()
returns uuid
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_role_id uuid;
  v_expected_permissions text[] := array[
    'approval.approve','approval.manage','approval.read','audit.read',
    'branch.access.manage','branch.access.read','branch.contact.manage',
    'branch.hours.manage','branch.manage','branch.profile.manage','branch.read',
    'branch.settings.manage','crm.manage','crm.read','dashboard.read',
    'document.manage','document.read','finance.manage','finance.read',
    'hr.manage','hr.read','inventory.manage','inventory.read','member.invite',
    'member.manage','member.read','module.manage','module.read','module.request',
    'notification.manage','organization.read','organization.update',
    'permission.read','purchase.manage','purchase.read','reports.read',
    'role.manage','role.read','sales.manage','sales.read','security.review'
  ];
  v_permission_count integer;
  v_module_count integer;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if not private.is_verified_platform_owner_v1() then
    raise exception 'Verified platform owner required' using errcode = '42501';
  end if;

  -- Serialize concurrent attempts and fail closed if any organization already exists.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('mr-rahaman-primary-organization-bootstrap-v1', 0)
  );

  if exists (select 1 from public.organizations) then
    raise exception 'Organization bootstrap is one-time and an organization already exists'
      using errcode = '55000';
  end if;

  -- Catalogue drift must be reviewed before granting a new or changed permission.
  select count(*) into v_permission_count from public.permissions;
  if v_permission_count <> pg_catalog.cardinality(v_expected_permissions)
     or exists (
       select permission_key from public.permissions
       except
       select pg_catalog.unnest(v_expected_permissions)
     )
     or exists (
       select pg_catalog.unnest(v_expected_permissions)
       except
       select permission_key from public.permissions
     ) then
    raise exception 'Permission catalogue differs from reviewed 41-key owner matrix'
      using errcode = '55000';
  end if;

  select count(*) into v_module_count from public.platform_modules;
  if v_module_count <> 16
     or not exists (select 1 from public.platform_modules where module_key='branch_management' and is_active)
     or not exists (select 1 from public.platform_modules where module_key='organization_management' and is_active) then
    raise exception 'Platform module registry differs from reviewed 16-module baseline'
      using errcode = '55000';
  end if;

  -- Require every mandatory dependency of a core/active module to also be core/active.
  if exists (
    select 1
    from public.platform_modules m
    join public.module_dependencies d on d.module_id = m.id and d.is_mandatory
    join public.platform_modules dep on dep.id = d.depends_on_module_id
    where m.is_core and m.is_active
      and not (dep.is_core and dep.is_active)
  ) then
    raise exception 'Core module has an inactive mandatory dependency'
      using errcode = '55000';
  end if;

  insert into public.organizations (
    organization_key, name, legal_name, status, timezone, currency_code, created_by
  ) values (
    'mr-rahaman-business-ecosystem',
    'MR RAHAMAN Business Ecosystem',
    'MR RAHAMAN Business Ecosystem',
    'pending',
    'Asia/Dhaka',
    'BDT',
    v_user_id
  ) returning id into v_org_id;

  insert into public.app_roles (
    organization_id, role_key, role_name, description, is_system, is_active
  ) values (
    v_org_id, 'owner', 'Owner',
    'Canonical organization owner role, assigned only by verified founder bootstrap',
    true, true
  ) returning id into v_role_id;

  insert into public.organization_members (
    organization_id, user_id, role_id, member_status, joined_at
  ) values (
    v_org_id, v_user_id, v_role_id, 'active', pg_catalog.now()
  );

  -- Full organization-level Owner matrix, only after exact 41-key catalogue validation.
  -- Platform-level authority remains separate in platform_admin_roles.
  insert into public.role_permissions (organization_id, role_id, permission_id)
  select v_org_id, v_role_id, p.id
  from public.permissions p
  where p.permission_key = any (v_expected_permissions);

  if not exists (
    select 1 from public.role_permissions rp
    where rp.organization_id = v_org_id and rp.role_id = v_role_id
    having count(*) = pg_catalog.cardinality(v_expected_permissions)
  ) then
    raise exception 'Owner permission matrix did not seed completely'
      using errcode = '55000';
  end if;

  -- Initialize all registry modules. Only currently active core modules are enabled.
  -- Optional/non-core modules remain disabled until separately approved.
  insert into public.organization_modules (
    organization_id, module_id, status, installed_version,
    enabled_at, enabled_by, configuration
  )
  select
    v_org_id,
    m.id,
    case when m.is_core and m.is_active then 'active' else 'disabled' end,
    case when m.is_core and m.is_active then m.current_version else null end,
    case when m.is_core and m.is_active then pg_catalog.now() else null end,
    case when m.is_core and m.is_active then v_user_id else null end,
    '{}'::jsonb
  from public.platform_modules m;

  if (select count(*) from public.organization_modules where organization_id=v_org_id) <> 16
     or not exists (
       select 1
       from public.organization_modules om
       join public.platform_modules m on m.id=om.module_id
       where om.organization_id=v_org_id
         and m.module_key='branch_management'
         and om.status='active'
     ) then
    raise exception 'Organization module initialization is incomplete'
      using errcode = '55000';
  end if;

  update public.organizations
     set status='active', updated_at=pg_catalog.now()
   where id=v_org_id and status='pending';

  if not found then
    raise exception 'Organization activation failed'
      using errcode = '55000';
  end if;

  insert into public.module_audit_logs (
    organization_id, actor_user_id, action, resource_type, resource_id,
    old_values, new_values
  ) values (
    v_org_id, v_user_id, 'organization.bootstrap_completed',
    'organization', v_org_id,
    pg_catalog.jsonb_build_object('status','not_created'),
    pg_catalog.jsonb_build_object(
      'status','active',
      'organization_key','mr-rahaman-business-ecosystem',
      'owner_user_id',v_user_id,
      'owner_role_id',v_role_id,
      'owner_permission_count',pg_catalog.cardinality(v_expected_permissions),
      'module_count',16
    )
  );

  return v_org_id;
end;
$function$;

-- Public RPC wrapper is intentionally narrow and parameterless.
create or replace function public.bootstrap_primary_organization_v1()
returns uuid
language sql
security definer
set search_path = ''
as $function$
  select private.bootstrap_primary_organization_v1();
$function$;

-- New functions inherit PUBLIC EXECUTE by default; revoke it explicitly.
revoke all on function private.bootstrap_primary_organization_v1() from public, anon, authenticated;
revoke all on function public.bootstrap_primary_organization_v1() from public, anon;
grant execute on function public.bootstrap_primary_organization_v1() to authenticated;

commit;

-- Review notes:
-- 1) This seeds all 41 current organization-scoped permissions to the canonical Owner role.
--    Platform role grants remain separate and are NOT created or modified here.
-- 2) Approval self-approval remains prohibited by the existing approval engine.
-- 3) This function must be tested in an isolated project with a real authenticated founder JWT.
-- 4) Do not run until triggers, RLS, ACLs, schema drift, and the permission matrix are independently reviewed.
